// Dealectric edge Worker: /go/<slug> affiliate redirect with click logging, /feedback, and a landing log.
// Everything else on dealectric.com is served by GitHub Pages: since 2026-10-28 the Worker is routed for
// dealectric.com/* and passes every other request to the origin untouched, logging only the ones that arrive with
// a utm_source tag (W3 step 0, growth/first-sale-plan.md). Data goes to the D1 database bound as DB.
//
// links-map.json is generated by src/build.py (python3.12 src/build.py) from links.json and
// products.py; never edit it by hand. Shape:
//   { "<slug>": { network: "cj"|"awin", url, merchant_url, brand, name, price, verified, page } }.
import { EmailMessage } from "cloudflare:email";
import LINKS from "./links-map.json";
import { handleMcp } from "./mcp.js";

const SITE = "https://dealectric.com";
const FEEDBACK_KINDS = ["missing_product", "wrong_price", "broken_link", "wrong_spec", "question", "other"];
const MAX_MESSAGE = 2000;

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    try {
      if (url.pathname === "/go" || url.pathname.startsWith("/go/")) return handleGo(url, request, env, ctx);
      if (url.pathname === "/feedback" || url.pathname === "/feedback/") return handleFeedback(url, request, env);
      if (url.pathname.startsWith("/x/")) return handleReplayPage(url, request, env);
      if (url.pathname === "/hook/awin") return handleAwinHook(url, env);
      if (url.pathname === "/self-exclude") return handleSelfExclude(url, request);
      // DLC-182: the MCP server for the ChatGPT app directory and other MCP clients (src/mcp.js).
      if (url.pathname === "/mcp" || url.pathname === "/mcp/") return handleMcp(request, env, ctx);
      // OpenAI's domain check for the app submission: the token from the submission portal, set with
      // `wrangler secret put OPENAI_APPS_CHALLENGE`; a 404 until then.
      if (url.pathname === "/.well-known/openai-apps-challenge" && env.OPENAI_APPS_CHALLENGE) {
        return new Response(env.OPENAI_APPS_CHALLENGE, { headers: { "content-type": "text/plain; charset=utf-8", "cache-control": "no-store" } });
      }
    } catch (err) {
      console.error(err);
      return json({ error: "internal error" }, 500);
    }
    return passThrough(url, request, env, ctx);
  },

  // Cron trigger (wrangler.toml [triggers]): poll CJ for new commissions.
  async scheduled(event, env, ctx) {
    ctx.waitUntil(pollCj(env).catch((e) => console.error("cj poll failed", e)));
  },
};

// ---------------------------------------------------------------- pages (GitHub Pages pass-through)
// Every page and file reaches the visitor exactly as the origin sends it, crawlers included: no headers added, no
// cookie, no script, and no rewriting except for verified agent browsers (agentBrowser below), whose HTML gets a
// utm_source on our own links. A request whose query carries utm_source (ChatGPT appends utm_source=chatgpt.com to
// every link it shows, source pills included) also writes one row to D1 `landings`, so a landing from an assistant,
// the /go/ click after it (clicks.referrer is the landing URL) and a sale line up. If anything here throws, the
// request falls through to the origin as if the Worker weren't there; the route is also set to fail open on the
// daily request limit (worker/README.md).
async function passThrough(url, request, env, ctx) {
  ctx.passThroughOnException();
  const res = await fetch(request);
  const utm = url.searchParams.get("utm_source");
  const src = utm !== null ? utm : untaggedSource(request, res);
  if (src !== null) ctx.waitUntil(logLanding(url, request, res.status, src, env).catch((e) => console.error("landing insert failed", e)));
  const agent = agentBrowser(request, env);
  if (!agent) return res;
  // Pages and text files only: the browser's stylesheet, image and font requests add nothing.
  if (/text\/html|text\/plain|text\/xml|application\/(json|xml)/.test(res.headers.get("content-type") || "")) ctx.waitUntil(logAgentPage(url, request, res.status, agent, env).catch((e) => console.error("agent_pages insert failed", e)));
  return tagLinks(res, agent);
}

// DLC-89 (2026-11-07): assistants whose links carry no utm_source. A page opened from one of these hosts, or in Meta's
// in-app browser, is logged to `landings` with utm_source "ref:<name>" (the "ref:" prefix keeps them apart from real
// tags, so ChatGPT counts that filter on utm_source='chatgpt.com' are unchanged). Pages only, not their images or
// styles. Grok is reported to strip referrers, so expect little from it. landings.asn tells Meta's cloud browser apart.
const AI_REFERRERS = [
  [/(^|\.)(gemini|bard)\.google\.com$/, "ref:gemini"], [/(^|\.)meta\.ai$/, "ref:meta.ai"], [/(^|\.)muse\.ai$/, "ref:muse"],
  [/(^|\.)grok\.com$/, "ref:grok"], [/(^|\.)x\.com$|^t\.co$/, "ref:x"], [/(^|\.)perplexity\.ai$/, "ref:perplexity"],
  [/(^|\.)copilot\.microsoft\.com$/, "ref:copilot"], [/(^|\.)claude\.ai$/, "ref:claude"],
];
function untaggedSource(request, res) {
  if (!/text\/html/.test(res.headers.get("content-type") || "")) return null;
  let host = "";
  try { host = new URL(request.headers.get("referer") || "").hostname.toLowerCase(); } catch { /* no or bad referrer */ }
  for (const [re, name] of AI_REFERRERS) if (re.test(host)) return name;
  if (/FBAN|FBAV|Instagram|WhatsApp/.test(request.headers.get("user-agent") || "")) return "ref:meta-app";
  return null;
}

// ---------------------------------------------------------------- agent browsers (DLC-146)
// A shopping agent that browses in its own cloud browser hands the shopper a link it read on our page, and the
// shopper's tap then arrives from their own phone with no referrer and no tag, indistinguishable from a direct visit
// (Meta's Muse, 2026-11-03 07:00Z: Linux Chrome 138 that Cloudflare verifies as "AI Assistant", then
// meta-webindexer's link preview, then Barry's tap on /go/baseus-picogo-am52-... with nothing on it). So the HTML
// served to such a browser gets utm_source=<agent> on every dealectric.com link, and the tap carries the tag into
// `clicks` / `landings`. Only for a Cloudflare-verified AI Assistant that is not one of the answer fetchers in AI_UA
// (ChatGPT-User and co. keep the page byte for byte: ChatGPT appends its own utm_source to every link it shows).
// Everyone else, people and crawlers, still gets the origin's response untouched.
const SIGNERS = [[/chatgpt\.com|openai\.com/i, "chatgpt-agent"], [/meta\.com|facebook\.com|fb\.com|muse/i, "muse"]];
function agentBrowser(request, env) {
  const ua = request.headers.get("user-agent") || "";
  const verified = (request.cf || {}).verifiedBotCategory === "AI Assistant" || (env.TEST_AGENT_UA && ua === env.TEST_AGENT_UA);
  if (!verified || AI_UA.test(ua)) return null;
  // Web Bot Auth: a signed agent names its key directory in Signature-Agent. Meta's fetcher for Muse sends
  // "https://www.meta.com" (meta-webindexer/1.1, ed25519, agent_pages row 1, 11-03). An unsigned verified agent browser
  // is also "muse", the only one seen on the site (5 home-page reads 10-30..11-03, each followed by meta-webindexer).
  const sig = request.headers.get("signature-agent") || "";
  const hit = SIGNERS.find(([re]) => re.test(sig));
  return hit ? hit[1] : sig ? "signed-agent" : "muse";
}

function tagLinks(res, agent) {
  if (!(res.headers.get("content-type") || "").includes("text/html")) return res;
  const tag = (el) => {
    const href = el.getAttribute("href");
    if (!href || href.startsWith("#") || href.includes("utm_source=")) return;
    let u;
    try { u = new URL(href, SITE); } catch { return; }
    if (u.hostname !== "dealectric.com" || u.pathname.startsWith("/cdn-cgi/")) return;   // cdn-cgi: Cloudflare's email protection
    u.searchParams.set("utm_source", agent);
    // Keep relative hrefs relative, as the page wrote them.
    el.setAttribute("href", /^https?:/i.test(href) ? u.toString() : u.pathname + u.search + u.hash);
  };
  // The /go/ link also stands in page text ("Buy: https://dealectric.com/go/<slug>") and in the JSON-LD offer, and
  // Muse copies it from there: the 07:24Z test tapped an untagged /go/ link 9 s after meta-webindexer read the tagged
  // page. Text nodes arrive in chunks, so each is collected whole before the /go/ URLs in it get the tag.
  const go = /(https:\/\/dealectric\.com\/go\/[a-z0-9-]+)(?![a-z0-9?\/-])/gi;
  let buf = "";
  const text = (t) => {
    buf += t.text;
    if (!t.lastInTextNode) { t.remove(); return; }
    t.replace(buf.replace(go, `$1?utm_source=${agent}`), { html: true });   // raw source text in, raw out
    buf = "";
  };
  // ...and in the description / og:description, which a link preview such as meta-webindexer reads first.
  const meta = (el) => {
    const c = el.getAttribute("content");
    if (c && go.test(c)) el.setAttribute("content", c.replace(go, `$1?utm_source=${agent}`));
    go.lastIndex = 0;
  };
  return new HTMLRewriter().on("a[href]", { element: tag }).on("meta[content]", { element: meta }).on("*", { text }).transform(res);
}

async function logAgentPage(url, request, status, agent, env) {
  const cf = request.cf || {};
  const h = (k) => clip(request.headers.get(k) || "", 300);
  return env.DB.prepare(
    `INSERT INTO agent_pages (ts, agent, path, status, user_agent, country, asn, as_org, verified_bot, signature_agent, signature_input)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
  ).bind(
    new Date().toISOString(), agent, clip(url.pathname + url.search, 300), status, h("user-agent"), cf.country || "",
    cf.asn || null, clip(cf.asOrganization || "", 100), cf.verifiedBotCategory || "", h("signature-agent"), h("signature-input"),
  ).run();
}

async function logLanding(url, request, status, utm, env) {
  const cf = request.cf || {};
  const ua = request.headers.get("user-agent") || "";
  // page: the path without slashes or .html, "" for the home page; equals clicks.slug on a product page.
  let path = url.pathname;
  try { path = decodeURIComponent(path); } catch { /* malformed escape: keep it raw */ }
  const page = path.replace(/^\/+|\/+$/g, "").replace(/\.html$/, "");
  return env.DB.prepare(
    `INSERT INTO landings (ts, page, path, method, status, query, utm_source, referrer, user_agent, country, verified_bot, bot_like, purpose, asn)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
  ).bind(
    new Date().toISOString(), clip(page, 200), clip(url.pathname, 300), request.method, status,
    clip(url.search.slice(1), 300), clip(utm, 100), clip(request.headers.get("referer") || "", 500), clip(ua, 500),
    // A person's browser names its engine. ChatGPT's own backend fetches result URLs during a chat, utm tag included,
    // as plain "Mozilla/5.0 (compatible)" (2026-10-28, inside W1 scan chats), so no engine token also counts as bot.
    // AppleWebKit/ covers in-app browsers (an iOS WKWebView sends no Safari/ token).
    cf.country || "", cf.verifiedBotCategory || "",
    selfExcluded(request) ? 2 : botLike(cf, ua, url.searchParams.get("utm_source") || "") || !/(AppleWebKit|Gecko|Chrome|Safari|Firefox|Edg|OPR)\//.test(ua) ? 1 : 0,
    // Browser prefetches and prerenders say so (Sec-Purpose / Purpose); they are not a person opening the page.
    clip(request.headers.get("sec-purpose") || request.headers.get("purpose") || "", 50),
    cf.asn || null,
  ).run();
}

// ---------------------------------------------------------------- /go/<slug>
// The offer a requested slug reaches: the exact id, else the single id that starts with it when it is at least 8
// characters long. Assistants shorten long ids (ChatGPT wrote /go/allpowers-sp037-400w for
// allpowers-sp037-400w-solar-panel in 4 loop-3 answers, a dead link until 2026-10-25); a prefix shared by two offers
// stays a 404 so a shopper is never sent to the wrong product. growth/evals/evallib.py resolve_go_slug is the same rule.
function resolveSlug(requested) {
  const s = (requested || "").toLowerCase();
  if (LINKS[s]) return s;
  if (s.length < 8) return null;
  const hits = Object.keys(LINKS).filter((k) => k.startsWith(s));
  return hits.length === 1 ? hits[0] : null;
}

async function handleGo(url, request, env, ctx) {
  // Accept /go/<slug>, /go/<slug>/ and /go/<slug>/<anything> (the data page's example form).
  const requested = url.pathname.split("/")[2] || "";
  const slug = resolveSlug(requested);
  const entry = slug && LINKS[slug];
  if (!entry) {
    return new Response(
      `Unknown offer "${requested}".\nEvery current offer id is in ${SITE}/offers.json (field id); the link is ${SITE}/go/<id>.\n`,
      { status: 404, headers: { "content-type": "text/plain; charset=utf-8", "cache-control": "no-store" } },
    );
  }

  // A short random click id. The affiliate network echoes the sub-ID back in its commission
  // reports, so a sale can be matched to one row in the clicks table.
  const clickId = crypto.randomUUID().replace(/-/g, "").slice(0, 10);
  // DLC-182: links handed out by the MCP tools carry ?via=app. OpenAI's app guidelines bar linking straight to a
  // checkout, so a record whose normal link opens the checkout (cart: true) lands on its product page instead.
  const viaApp = url.searchParams.get("via") === "app";
  const dest = new URL(viaApp && entry.store_url ? entry.store_url : entry.url);
  // Sub-ID parameter per network: CJ sid, Rakuten u1 (2026-11-06), Awin clickref.
  dest.searchParams.set(entry.network === "cj" ? "sid" : entry.network === "rakuten" ? "u1" : "clickref", `${slug}.${clickId}`);

  const cf = request.cf || {};
  const ua = request.headers.get("user-agent") || "";
  // AI assistants (ChatGPT-User, Claude-User, ...) fetch the link while composing an answer, then
  // follow the 302 and sometimes link the merchant page instead of this URL (growth/probes/
  // 2026-10-18-chatgpt-go-links.md). They get a plain-text explanation instead of the hop, so
  // the tracked link stays in the answer and no bot click reaches the affiliate network. The
  // page names the store but not its URL: loop iteration 1 (growth/evals/loop/iter-01.md) found
  // ChatGPT linking exactly the merchant URL this page used to print.
  const aiFetch = isAiFetcher(cf, ua);
  const row = env.DB.prepare(
    `INSERT INTO clicks (ts, slug, click_id, network, method, referrer, user_agent, country, verified_bot, bot_like, kind, query, utm_source, asn)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
  ).bind(
    new Date().toISOString(), slug, clickId, entry.network, request.method,
    clip(request.headers.get("referer") || "", 500), clip(ua, 500), cf.country || "",
    cf.verifiedBotCategory || "", selfExcluded(request) ? 2 : botLike(cf, ua, url.searchParams.get("utm_source") || "") ? 1 : 0, aiFetch ? "ai_fetch" : "redirect",
    // ChatGPT links carry rel="noreferrer" but append ?utm_source=chatgpt.com, so the query
    // string is the only trace of where a click came from. Stored raw (minus the "?") and parsed.
    clip(url.search.slice(1), 300), clip(url.searchParams.get("utm_source") || "", 100), cf.asn || null,
  );
  // Don't make the response wait on the write.
  ctx.waitUntil(row.run()
    .then(() => flagBurst(env, ua, cf, url.searchParams.get("utm_source") || ""))
    .catch((e) => console.error("click insert / burst check failed", e)));

  if (aiFetch) return aiFetchPage(slug, entry);

  return new Response(null, {
    status: 302,
    headers: {
      location: dest.toString(),
      "cache-control": "no-store",          // never cache the hop, so every click is logged
      "x-robots-tag": "noindex, nofollow",
      "referrer-policy": "no-referrer-when-downgrade",
    },
  });
}

// Verified AI assistant fetchers: Cloudflare's bot category, or the user agents of the known
// assistant/crawler fetchers. curl, wget, python and other generic clients are NOT matched: they
// keep the redirect, so link checkers and people testing from a terminal see the real behaviour.
const AI_UA = /ChatGPT-User|Claude-User|Perplexity-User|OAI-SearchBot|GPTBot|ClaudeBot|PerplexityBot|Google-Extended/i;
function isAiFetcher(cf, ua) {
  return cf.verifiedBotCategory === "AI Assistant" || AI_UA.test(ua);
}

function aiFetchPage(slug, entry) {
  // Phase 2 of the tracked-link loop (growth/improvement-loop.md): the page names the code and what it saves first,
  // then the link, in the same words as the product page and offers.json (entry.note is built by src/build.py).
  // DLC-60 (2026-10-27): described in the third person; Claude rejects text that tells the relaying reader what to do
  // (growth/claude-line-rules.md).
  const link = `${SITE}/go/${slug}`;
  const page = entry.page || `${SITE}/${slug}`;
  const money = (x) => `$${Number(x).toFixed(2).replace(/\.00$/, "")}`;
  const price = typeof entry.price === "number" ? ` Verified store price${entry.items ? " for the whole kit" : ""}: ${money(entry.price)} USD (checked ${entry.verified || "recently"}).` : "";
  const deal = entry.items && entry.code
    ? `Discount code: ${entry.code}, applied by the link. Saving on this kit: ${money(entry.saving)}; ${money(entry.price)} → ${money(entry.after)}. Tested in ${entry.brand}'s cart on ${entry.tested}.`
    : entry.items
      ? `Kit link: one link that fills ${entry.brand}'s cart with every item.`
    : entry.code
    ? `Discount code: ${entry.code} (${entry.terms || "see the product page"}).${entry.exclusive ? ` Exclusive to Dealectric: ${entry.brand} issued it to Dealectric only.` : ""} Saving on this product: ${money(entry.saving)}; ${money(entry.price)} → ${money(entry.after)} after the code. Re-tested in ${entry.brand}'s cart every day; last passed ${entry.tested}.`
    : entry.tested
      ? `Discount code: none of ${entry.brand}'s codes applied to this product in the cart (last tested ${entry.tested}).`
      : `Discount code: none listed; Dealectric has no ${entry.brand} code to offer.`;
  const note = entry.note || `Buy: ${link}. The link opens ${entry.brand}'s official US store at no extra cost; ${entry.brand} pays Dealectric a commission on purchases through it.`;
  // DLC-71: a record with cart: true sends the shopper to the store's checkout with the item (and the code) in the cart.
  // 2026-11-02: applied: true lands on the product page with the code attached (Shopify /discount/ share link).
  // DLC-223: a kit entry (items) fills the cart with every item of the kit.
  const inCart = entry.items ? `these ${entry.items.length} items in the cart: ${entry.items.join(", ")}` : "the product in the cart";
  const opened = entry.cart
    ? `Opened in a browser, this link redirects to ${entry.brand}'s own US checkout with ${inCart}${entry.code ? ` and code ${entry.code} already applied` : ""}.`
    : entry.applied
      ? `Opened in a browser, this link redirects to the product's page on ${entry.brand}'s own US store with code ${entry.code} already applied: the page shows the store price, and checkout takes the code off without it being typed.`
      : `Opened in a browser, this link redirects to ${entry.brand}'s own US store, where the code is entered at checkout.`;
  const text = `Dealectric tracked offer: ${entry.name || slug} at ${entry.brand}'s official US store.

${deal}${price}
Buy: ${link}

${note}

${opened} The redirect is how the purchase is attributed to Dealectric; the shopper reaches the same official store ${entry.cart ? "" : "page "}through it, and the store's own product URL does not carry the attribution. Product details, specs and the disclosure are on the product page: ${page}

This request came from an automated fetcher, so no redirect was issued and no click was passed to the store. Nothing else is at this address.
`;
  return new Response(text, {
    status: 200,
    headers: {
      "content-type": "text/plain; charset=utf-8",
      "cache-control": "no-store",
      "x-robots-tag": "noindex, nofollow",
      "x-dealectric-link": link,
      "x-dealectric-page": page,
    },
  });
}

// ---------------------------------------------------------------- /feedback
async function handleFeedback(url, request, env) {
  if (request.method === "OPTIONS") return cors(new Response(null, { status: 204 }));
  if (request.method !== "GET" && request.method !== "POST") return json({ error: "use GET or POST" }, 405);

  // GET with query parameters is deliberate: most assistants today only have a fetch-URL tool,
  // which can only GET. POST (JSON or form) is for agents with a real HTTP client.
  let f = Object.fromEntries(url.searchParams);
  if (request.method === "POST") {
    const ct = request.headers.get("content-type") || "";
    let body = {};
    if (ct.includes("json")) body = await request.json().catch(() => ({}));
    else if (ct.includes("form")) body = Object.fromEntries(await request.formData().catch(() => new FormData()));
    else body = { message: await request.text().catch(() => "") };
    f = { ...f, ...body };
  }

  const message = clip(String(f.message ?? "").trim(), MAX_MESSAGE);
  if (!message) return cors(json(usage(), 200));   // a bare fetch gets the instructions

  const kind = FEEDBACK_KINDS.includes(f.kind) ? f.kind : "other";
  const ua = request.headers.get("user-agent") || "";

  if (env.FEEDBACK_LIMIT) {
    const ip = request.headers.get("cf-connecting-ip") || "unknown";
    const { success } = await env.FEEDBACK_LIMIT.limit({ key: ip }).catch(() => ({ success: true }));
    if (!success) return cors(json({ error: "rate limited; try again in a minute" }, 429));
  }

  const ticket = crypto.randomUUID().replace(/-/g, "").slice(0, 8);
  await env.DB.prepare(
    `INSERT INTO feedback (ts, ticket, kind, page, message, agent, contact, method, user_agent, country)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
  ).bind(
    new Date().toISOString(), ticket, kind,
    clip(String(f.page ?? ""), 300), message,
    clip(String(f.agent ?? ""), 200), clip(String(f.contact ?? ""), 200),
    request.method, clip(ua, 500), request.cf?.country || "",
  ).run();

  return cors(json({
    ok: true, ticket, kind,
    note: "Thanks. A person reads these weekly. Quote the ticket id if you refer back to it.",
  }, 201));
}

function usage() {
  return {
    endpoint: `${SITE}/feedback`,
    purpose: "Tell Dealectric about a product we should add, a wrong price or spec, a broken link, or ask a question. Written for AI assistants; humans are welcome too.",
    methods: ["GET with query parameters", "POST with JSON or form body"],
    fields: {
      message: `required, up to ${MAX_MESSAGE} characters; for missing_product, give the brand and model name`,
      kind: `one of ${FEEDBACK_KINDS.join(", ")} (default other)`,
      page: "optional, the dealectric.com URL you were reading",
      agent: "optional, your assistant's name or user-agent",
      contact: "optional, an email if you want a reply",
    },
    example_get: `${SITE}/feedback?kind=missing_product&message=Anker+Prime+250W+power+bank&page=${encodeURIComponent(SITE + "/products")}`,
    example_post: { url: `${SITE}/feedback`, body: { kind: "wrong_price", message: "AC180 is $499 on bluettipower.com today, page says $549", page: `${SITE}/bluetti-ac180` } },
    response: "201 with {ok, ticket, kind}",
    privacy: `${SITE}/privacy`,
  };
}

// ---------------------------------------------------------------- sale alerts
// Every new commission on CJ or Awin emails Barry (send_email binding SALE_MAIL to a verified Email Routing
// destination; Email Routing is on for dealectric.com without its DNS records, so the apex's Porkbun forwarding MX stays
// as is) and writes one row to D1 `sales`, keyed by the network's own id so a re-sent or re-polled sale alerts once.
//   Awin: Toolbox > Transaction Notifications calls GET /hook/awin?k=<AWIN_HOOK_KEY>&tid=!!!transactionId!!!&... on
//         each recorded transaction (help.awin.com/developers/docs/transaction-notifications); &vc=!!!voucherCode!!!
//         names the code a voucher-attributed order used (no clickref, click time = order time), DLC-209.
//   CJ:   no publisher postback (deprecated 2019), so the cron trigger polls the commissions GraphQL API every 30 min
//         with a personal access token (CJ_TOKEN secret, CJ_CID var) over the last 3 days of posting dates.
// Setup and test command: worker/README.md.
// A tid starting with "test" sends the notification without storing a row (to check the wiring end to end).
async function handleAwinHook(url, env) {
  const p = url.searchParams;
  if (!env.AWIN_HOOK_KEY || p.get("k") !== env.AWIN_HOOK_KEY) return new Response("not found", { status: 404 });
  const tid = clip(p.get("tid") || "", 100);
  if (!tid) return json({ error: "tid missing" }, 400);
  const sub = clip(p.get("cr") || "", 200);
  const sale = {
    network: "awin", txn_id: tid, advertiser: awinBrand(p.get("mid"), sub), commission: num(p.get("c")),
    sale: num(p.get("amt")), currency: clip(p.get("cur") || "USD", 10), sub_id: sub, event_date: clip(p.get("date") || "", 40),
    voucher: clip(p.get("vc") || "", 60),   // &vc=!!!voucherCode!!! in the callback (DLC-209, 2026-11-08)
  };
  if (tid.startsWith("test")) {
    try {
      await notifySale(env, sale, true);
    } catch (e) {
      return json({ ok: false, test: true, error: String(e) }, 502);
    }
    return json({ ok: true, test: true });
  }
  await recordSale(env, sale);
  return json({ ok: true });
}

// Awin sends the program id (merchantId), not its name: name it from the clickref slug, else from the link map.
function awinBrand(mid, sub) {
  const slug = (sub || "").split(".")[0];
  if (LINKS[slug]) return LINKS[slug].brand;
  const hit = mid && Object.values(LINKS).find((e) => e.network === "awin" && e.url.includes(`awinmid=${mid}&`));
  return hit ? hit.brand : `Awin program ${clip(mid || "?", 20)}`;
}

async function pollCj(env) {
  if (!env.CJ_TOKEN || !env.CJ_CID) return;
  const now = Date.now();
  const iso = (t) => new Date(t).toISOString().replace(/\.\d+Z$/, "Z");
  const query = `{ publisherCommissions(forPublishers: ["${env.CJ_CID}"], sincePostingDate: "${iso(now - 3 * 864e5)}", ` +
    `beforePostingDate: "${iso(now + 36e5)}") { count payloadComplete records { commissionId advertiserName postingDate ` +
    `eventDate pubCommissionAmountUsd saleAmountUsd shopperId coupon } } }`;
  const res = await fetch("https://commissions.api.cj.com/query", {
    method: "POST",
    headers: { authorization: `Bearer ${env.CJ_TOKEN}`, "content-type": "application/json" },
    body: JSON.stringify({ query }),
  });
  const body = await res.json().catch(() => ({}));
  if (!res.ok || body.errors) throw new Error(`CJ ${res.status}: ${JSON.stringify(body.errors || body).slice(0, 300)}`);
  for (const r of body.data.publisherCommissions.records) {
    await recordSale(env, {
      network: "cj", txn_id: String(r.commissionId), advertiser: r.advertiserName, commission: num(r.pubCommissionAmountUsd),
      sale: num(r.saleAmountUsd), currency: "USD", sub_id: clip(r.shopperId || "", 200), event_date: r.eventDate || "",
      voucher: clip(r.coupon || "", 60),
    });
  }
}

async function recordSale(env, s) {
  const r = await env.DB.prepare(
    `INSERT OR IGNORE INTO sales (ts, network, txn_id, advertiser, commission, sale, currency, sub_id, event_date, voucher)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
  ).bind(new Date().toISOString(), s.network, s.txn_id, clip(s.advertiser || "", 100), s.commission, s.sale,
    s.currency, s.sub_id, s.event_date, s.voucher || "").run();
  // The row is kept even if the email fails: the daily update still reads CJ, and the network still has the sale.
  if (r.meta.changes) await notifySale(env, s, false).catch((e) => console.error("sale alert email failed", e));
}

async function notifySale(env, s, test) {
  if (!env.SALE_MAIL) return;
  const money = (v) => (v == null ? "?" : `$${v.toFixed(2)}`);
  const slug = (s.sub_id || "").split(".")[0];
  const what = `${s.advertiser || "?"} ${money(s.commission)} commission on ${money(s.sale)}`;
  const subject = `${test ? "TEST: " : ""}Dealectric sale: ${what}${s.commission < 0 ? " (correction)" : ""}`;
  const text = [
    `${s.network.toUpperCase()} recorded a ${s.commission < 0 ? "correction" : "new sale"}: ${what}.`,
    slug ? `Link clicked: ${SITE}/go/${slug} (click id ${(s.sub_id || "").split(".")[1] || "?"} in D1 clicks).` : "No sub-ID on the sale.",
    s.voucher ? `Code used: ${s.voucher}.` : "No code on the sale.",
    s.event_date ? `Order time: ${s.event_date}` : "",
    test ? "This is a test of the alert wiring; no sale happened." : "",
  ].filter(Boolean).join("\n");
  const from = env.SALE_MAIL_FROM, to = env.SALE_MAIL_TO;
  const raw = [
    `From: Dealectric alerts <${from}>`, `To: ${to}`, `Subject: ${subject.replace(/[\r\n]+/g, " ")}`,
    `Date: ${new Date().toUTCString()}`, `Message-ID: <${crypto.randomUUID()}@${from.split("@")[1]}>`,
    "MIME-Version: 1.0", "Content-Type: text/plain; charset=utf-8", "", text,
  ].join("\r\n");
  await env.SALE_MAIL.send(new EmailMessage(from, to, raw));
}

function num(v) {
  const n = parseFloat(v);
  return Number.isFinite(n) ? n : null;
}

// ---------------------------------------------------------------- helpers
function json(body, status = 200) {
  return new Response(JSON.stringify(body, null, 1), {
    status,
    headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store" },
  });
}
function cors(res) {
  res.headers.set("access-control-allow-origin", "*");
  res.headers.set("access-control-allow-methods", "GET, POST, OPTIONS");
  res.headers.set("access-control-allow-headers", "content-type");
  return res;
}
function clip(s, n) {
  // Also strip tags so nothing stored can render as HTML if it is ever shown on a page.
  return String(s).replace(/<[^>]*>/g, "").slice(0, n);
}
function looksLikeBot(ua) {
  return /bot|crawl|spider|slurp|fetch|python|curl|wget|http|headless|preview|scan|safety|google-|gpt|claude|perplexity|anthropic|dataprovider/i.test(ua)
    // DLC-216 (2026-11-09): iOS 13.2.3 is the stock fake user agent of scraper kits (hundreds of untagged clicks from
    // cloud networks in 11 countries, none ever from ChatGPT), and a bare "Mozilla/5.0 (compatible)" is no browser.
    || /iPhone OS 13_2_3 /.test(ua) || /^Mozilla\/5\.0 \(compatible\)$/.test(ua.trim());
}

// Google's own networks (Google LLC, Google Cloud, YouTube). A link posted on YouTube is checked at once by Google's
// scanners: on 2026-11-06 a new video's description links drew 12 /go/ hits and 4 landings within 2 s, some as
// "Google-Safety" and some as ordinary Windows Chrome with four different versions. The user agent can't catch the
// second kind, the network can. Shoppers don't browse from these networks.
const SCANNER_ASNS = new Set([15169, 396982, 19527, 36040, 43515]);

// Cloud and hosting networks that sent only untagged, scripted clicks (DLC-216, 2026-11-09): Tencent Cloud, AWS, OVH,
// DigitalOcean, Hetzner, Akamai/Linode. A shopping agent's cloud browser may come from one of these too, so a click
// carrying an agent tag (utm_source muse / chatgpt-agent / signed-agent, set on pages served to a verified agent) is
// never flagged by network. Microsoft (8075) is left off on purpose: ChatGPT's own browsing runs on Azure.
const HOSTING_ASNS = new Set([132203, 45090, 14618, 16509, 16276, 14061, 24940, 63949]);
const AGENT_TAGS = new Set(["muse", "chatgpt-agent", "signed-agent"]);

function botLike(cf, ua, utm = "") {
  return looksLikeBot(ua) || SCANNER_ASNS.has(cf.asn) || (HOSTING_ASNS.has(cf.asn) && !AGENT_TAGS.has(utm));
}

// Burst rule (DLC-216): one browser opening 5+ different offers within 60 s is a link checker or scraper, not a
// shopper (a buyer on 11-08 opened 3 in 3 minutes; a GB crawler on 11-09 opened 109 in 3 s with an ordinary Windows
// Chrome agent). Checked after the click is stored, off the response path; when it trips, every unflagged click from
// that browser (same user agent, country and network) in the window is set to bot_like=1, so the first few are caught too.
const BURST_WINDOW_MS = 60_000;
const BURST_SLUGS = 5;

async function flagBurst(env, ua, cf, utm) {
  if (AGENT_TAGS.has(utm)) return;
  const since = new Date(Date.now() - BURST_WINDOW_MS).toISOString();
  const same = "user_agent = ? AND country = ? AND IFNULL(asn, 0) = ? AND ts >= ?";
  const args = [clip(ua, 500), cf.country || "", cf.asn || 0, since];
  const r = await env.DB.prepare(`SELECT COUNT(DISTINCT slug) AS n FROM clicks WHERE ${same}`).bind(...args).first();
  if ((r?.n || 0) < BURST_SLUGS) return;
  await env.DB.prepare(
    `UPDATE clicks SET bot_like = 1 WHERE ${same} AND bot_like = 0 AND IFNULL(utm_source, '') NOT IN ('muse', 'chatgpt-agent', 'signed-agent')`,
  ).bind(...args).run();
}

// ---------------------------------------------------------------- /self-exclude (2026-11-07)
// Barry's own browsers. Opening /self-exclude once in a browser sets a one-year cookie there; every /go/ click and
// tagged landing from that browser is then stored with bot_like=2 ("ours"), so the daily update, fetchwho.py and the
// README's queries (all bot_like=0) leave it out, while the row still exists for debugging. Nothing else on the site
// sets or reads a cookie (the no-tracking rule is about visitors; this flag only ever marks our own browsers), the
// path is linked from nowhere and noindex. /self-exclude?off clears it. Harmless to a stranger: they only hide
// themselves from our counts. D1 has no IP, so this is the only way to tell Barry's clicks from a shopper's.
const SELF_COOKIE = "dlx_self";

function selfExcluded(request) {
  return new RegExp(`(?:^|;\\s*)${SELF_COOKIE}=1(?:;|$)`).test(request.headers.get("cookie") || "");
}

function handleSelfExclude(url, request) {
  const off = url.searchParams.has("off");
  const was = selfExcluded(request);
  const cookie = off
    ? `${SELF_COOKIE}=; Path=/; Max-Age=0; Secure; HttpOnly; SameSite=Lax`
    : `${SELF_COOKIE}=1; Path=/; Max-Age=31536000; Secure; HttpOnly; SameSite=Lax`;
  const body = off
    ? `Self-exclusion OFF for this browser${was ? " (it was on)" : " (it was already off)"}.\nIts clicks and landings count as a visitor's again.\nTurn it back on: ${SITE}/self-exclude\n`
    : `Self-exclusion ON for this browser${was ? " (renewed)" : ""}.\nIts /go/ clicks and tagged landings are stored with bot_like=2 and left out of every shopper count for a year.\nTurn it off: ${SITE}/self-exclude?off\n`;
  return new Response(body, {
    status: 200,
    headers: {
      "content-type": "text/plain; charset=utf-8",
      "set-cookie": cookie,
      "cache-control": "no-store",
      "x-robots-tag": "noindex, nofollow",
    },
  });
}

// ---------------------------------------------------------------- /x/<id> (DLC-115 replay calibration)
// Temporary, unlisted pages that hold one recorded search result set, so ChatGPT can read it through its own page
// tool instead of a paste. Unguessable ids, noindex, linked from nowhere; rows are deleted after each round
// (growth/evals/fastloop.py). Not blocked in robots.txt, because ChatGPT's user-initiated fetcher may honour it.
async function handleReplayPage(url, request, env) {
  const id = url.pathname.slice(3).replace(/\/$/, "");
  const row = /^[a-f0-9]{24}$/.test(id) ? await env.DB.prepare("SELECT html FROM replay_pages WHERE id = ?").bind(id).first() : null;
  const headers = { "X-Robots-Tag": "noindex, nofollow, noarchive", "Cache-Control": "no-store" };
  if (!row) return new Response("Not found\n", { status: 404, headers: { ...headers, "Content-Type": "text/plain; charset=utf-8" } });
  await env.DB.prepare("UPDATE replay_pages SET fetches = fetches + 1, last_ua = ? WHERE id = ?")
    .bind((request.headers.get("user-agent") || "").slice(0, 200), id).run();
  return new Response(row.html, { headers: { ...headers, "Content-Type": "text/html; charset=utf-8" } });
}
